body.script:
(function(){
  var frame = document.getElementById("aether-static-frame");
  var payload = "";
  var target = "data:text/html;base64," + payload;
  var query = "";
  try {
    query = window.location.search || "";
    if (query && query.charAt(0) === "?") {
      target += "#" + encodeURIComponent(query);
    }
  } catch (err) {}
  frame.src = target;
})();
